mapper.update:
UPDATE user_account
SET total_amount = total_amount - #{amount},
	available_amount = available_amount - #{amount}
WHERE
	user_id = #{userId}
  AND #{amount} > 0
  AND available_amount >= #{amount}
  AND is_deleted = 0

UPDATE user_account
SET total_amount = total_amount + #{amount},
	available_amount = available_amount + #{amount}
WHERE
	user_id = #{userId}
  AND is_deleted = 0
